css:
html, body {
    font-size: 10px !important;
    margin: 0 !important;
    padding: 0 !important;
}

@page {
    size: A4 portrait;
    margin: 3mm 3mm 3mm 3mm;
}

.ssa-container {
    border: 2px solid #000;
    padding: 3px;
    font-family: Arial, sans-serif;
    font-size: 10px;
    width: 100%;
    box-sizing: border-box;
    page-break-inside: avoid;
}

.ssa-header {
    text-align: center;
    margin-bottom: 2px;
    border-bottom: 2px solid #000;
    padding-bottom: 1px;
}
.ssa-company-name {
    margin: 0;
    font-size: 13px;
    font-weight: bold;
    color: #000;
}
.ssa-doc-title {
    background-color: #e8e8e8;
    text-align: center;
    padding: 1px;
    margin-bottom: 2px;
    border: 1px solid #000;
    font-size: 11px;
    font-weight: bold;
    color: #000;
}

.summary-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    table-layout: fixed;
    margin-bottom: 2px;
    page-break-inside: avoid;
}
.summary-table .summary-title {
    background-color: #e8e8e8;
    font-weight: bold;
    font-size: 10px;
    padding: 1px 4px;
    text-align: left;
    border-bottom: 1px solid #000;
    color: #000;
}
.summary-table tbody tr:nth-child(even) { background-color: #f9f9f9; }
.summary-table tbody tr:nth-child(odd)  { background-color: #fff; }
.summary-table .lbl {
    font-weight: 600;
    padding: 1px 4px;
    color: #000;
    font-size: 10px;
    width: 18%;
    border-right: 1px solid #ddd;
}
.summary-table .val {
    padding: 1px 4px;
    color: #333;
    font-size: 10px;
    width: 32%;
}

.ssa-statutory {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-bottom: 2px;
    padding: 2px 4px;
    background: #f9f9f9;
    border: 1px solid #000;
    align-items: center;
    font-size: 10px;
}
.ssa-badge {
    padding: 1px 5px;
    border-radius: 10px;
    font-size: 9px;
    font-weight: 700;
}
.ssa-badge-yes {
    background: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}
.ssa-badge-no {
    background: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.ssa-main-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 0;
    table-layout: fixed;
    font-size: 10px;
    page-break-inside: avoid;
}
.ssa-main-table .col-header {
    background-color: #dbeafe;
    padding: 2px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    text-align: center;
    color: #000;
}
.ssa-main-table .sub-header {
    background-color: #fff;
    padding: 1px 3px;
    border: 1px solid #000;
    font-size: 9px;
    color: #000;
}
.ssa-main-table .sub-left  { text-align: left; }
.ssa-main-table .sub-right { text-align: right; }
.ssa-main-table .data-label {
    padding: 1px 3px;
    border: 1px solid #000;
    font-size: 10px;
    color: #000;
    word-wrap: break-word;
    line-height: 1.1;
}
.ssa-main-table .data-value {
    padding: 1px 3px;
    border: 1px solid #000;
    font-size: 10px;
    text-align: right;
    color: #000;
    white-space: nowrap;
    line-height: 1.1;
}
.ssa-main-table tfoot .total-row {
    background-color: #e8e8e8;
    font-weight: bold;
}
.ssa-main-table .total-label {
    padding: 2px 3px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    color: #000;
}
.ssa-main-table .total-value {
    padding: 2px 3px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    text-align: right;
    color: #000;
}

.ssa-emp-wrap {
    margin-top: 2px;
    border: 1px solid #000;
}
.ssa-emp-header {
    background-color: #dbeafe;
    padding: 2px;
    border-bottom: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    text-align: center;
    color: #000;
}
.ssa-emp-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    border-top: none;
}
.ssa-emp-col {
    border-right: 1px solid #000;
}
.ssa-emp-col:last-child { border-right: none; }
.ssa-emp-col table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}
.ssa-emp-col table thead td {
    background: #fff;
    padding: 1px 3px;
    border-bottom: 1px solid #000;
    font-size: 9px;
    font-weight: 600;
    color: #000;
}
.ssa-emp-col table thead td.r { text-align: right; }
.ssa-emp-col table tbody td {
    padding: 1px 3px;
    border-bottom: 1px solid #eee;
    font-size: 10px;
    color: #000;
    line-height: 1.1;
}
.ssa-emp-col table tbody td.r { text-align: right; }
.ssa-emp-total {
    border-top: 1px solid #000;
    padding: 2px 4px;
    display: flex;
    justify-content: space-between;
    font-weight: bold;
    font-size: 10px;
    background: #e8e8e8;
}

.ssa-net-box {
    background-color: #d1fae5;
    padding: 3px;
    text-align: center;
    border: 2px solid #000;
    margin-top: 2px;
}
.ssa-net-amount {
    font-weight: bold;
    font-size: 11px;
    margin: 0;
    color: #000;
}
.ssa-net-sub {
    font-size: 10px;
    margin: 0;
    color: #000;
}

.ssa-ctc-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-top: 2px;
    page-break-inside: avoid;
}
.ssa-ctc-table td {
    padding: 1px 4px;
    border: 1px solid #000;
    color: #000;
}
.ssa-ctc-table .lbl {
    font-weight: 600;
    background: #e8e8e8;
    width: 25%;
}
.ssa-ctc-table .val {
    text-align: right;
    width: 25%;
}

@media print {
    html, body { margin: 0 !important; padding: 0 !important; }
    .ssa-container { border: 2px solid #000; page-break-inside: avoid; }
}
